using System.Text;
using AutoNexus.Application.DTOs;
using AutoNexus.Application.Interfaces;
using AutoNexus.Domain.Enums;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using AutoNexus.Infrastructure.Data;
using AutoNexus.Domain.Interfaces;
namespace AutoNexus.Api.Controllers;
[ApiController]
[Route("api/public")]
public class PublicCatalogController : ControllerBase
{
    private readonly AutoNexusDbContext _context; private readonly IVehicleService _vehicleService; private readonly IFeedExportService _feedExportService; private readonly IAiDescriptionService _aiDescriptionService; private readonly ITenantContext _tenantContext;
    public PublicCatalogController(AutoNexusDbContext context,IVehicleService vehicleService,IFeedExportService feedExportService,IAiDescriptionService aiDescriptionService,ITenantContext tenantContext){_context=context;_vehicleService=vehicleService;_feedExportService=feedExportService;_aiDescriptionService=aiDescriptionService;_tenantContext=tenantContext;}
    [HttpGet("catalog/current")][Authorize] public async Task<IActionResult> GetCurrentTenantCatalog(CancellationToken cancellationToken){if(!_tenantContext.HasTenant)return Unauthorized(new{message="Não foi possível identificar a empresa da sessão."});var tenant=await _context.Tenants.AsNoTracking().SingleOrDefaultAsync(t=>t.Id==_tenantContext.TenantId&&t.IsActive,cancellationToken);if(tenant==null)return NotFound(new{message="Empresa não encontrada ou inativa."});return await GetPublicCatalog(tenant.Slug,cancellationToken);}
    [HttpGet("catalog")][AllowAnonymous] public async Task<IActionResult> GetPublicCatalog([FromQuery]string? store,CancellationToken cancellationToken){AllowPublicCatalogCors();var slug=string.IsNullOrWhiteSpace(store)?"default":store.Trim().ToLowerInvariant();var tenant=await _context.Tenants.AsNoTracking().SingleOrDefaultAsync(t=>t.Slug==slug&&t.IsActive,cancellationToken);if(tenant==null)return NotFound(new{message="Loja não encontrada ou inativa."});var settings=await _context.TenantSettings.IgnoreQueryFilters().AsNoTracking().Where(s=>s.TenantId==tenant.Id).Select(s=>new{s.CompanyName,s.LogoUrl,s.PrimaryColor,s.WhatsAppNumber}).FirstOrDefaultAsync(cancellationToken);var vehicles=await _context.Vehicles.IgnoreQueryFilters().AsNoTracking().Where(v=>v.TenantId==tenant.Id&&v.Status==VehicleStatus.AVenda).Include(v=>v.VehicleType).Include(v=>v.Photos).OrderByDescending(v=>v.CreatedAt).Select(v=>new{id=v.Id,vehicleTypeName=v.VehicleType.Name,brand=v.Brand,model=v.Model,version=v.Version,manufacturingYear=v.ManufacturingYear,modelYear=v.ModelYear,mileage=v.Mileage,color=v.Color,fuel=v.Fuel.HasValue?v.Fuel.Value.ToString():null,transmission=v.Transmission.HasValue?v.Transmission.Value.ToString():null,status=v.Status.ToString(),listedValue=v.ListedValue,mainPhotoUrl=v.Photos.Where(p=>p.IsMain).Select(p=>p.StoragePath).FirstOrDefault()??v.Photos.Select(p=>p.StoragePath).FirstOrDefault(),createdAt=v.CreatedAt}).ToListAsync(cancellationToken);return Ok(new{store=new{name=settings?.CompanyName??tenant.Name,slug=tenant.Slug,logoUrl=settings?.LogoUrl,primaryColor=settings?.PrimaryColor??"#2563eb",whatsappNumber=settings?.WhatsAppNumber},items=vehicles});}
    [HttpGet("catalog/{id:guid}")][AllowAnonymous] public async Task<IActionResult> GetPublicVehicleDetails(Guid id,[FromQuery]string? store,CancellationToken cancellationToken){AllowPublicCatalogCors();var slug=string.IsNullOrWhiteSpace(store)?"default":store.Trim().ToLowerInvariant();var tenant=await _context.Tenants.AsNoTracking().SingleOrDefaultAsync(t=>t.Slug==slug&&t.IsActive,cancellationToken);if(tenant==null)return NotFound(new{message="Loja não encontrada ou inativa."});var vehicle=await _context.Vehicles.IgnoreQueryFilters().AsNoTracking().Where(v=>v.Id==id&&v.TenantId==tenant.Id&&v.Status==VehicleStatus.AVenda).Include(v=>v.VehicleType).Include(v=>v.Photos).Include(v=>v.Documents).ThenInclude(d=>d.DocumentCategory).FirstOrDefaultAsync(cancellationToken);if(vehicle==null)return NotFound(new{message="Veículo não encontrado no catálogo desta loja."});return Ok(new{id=vehicle.Id,vehicleTypeName=vehicle.VehicleType.Name,brand=vehicle.Brand,model=vehicle.Model,version=vehicle.Version,manufacturingYear=vehicle.ManufacturingYear,modelYear=vehicle.ModelYear,mileage=vehicle.Mileage,color=vehicle.Color,fuel=vehicle.Fuel?.ToString(),transmission=vehicle.Transmission?.ToString(),status=vehicle.Status.ToString(),listedValue=vehicle.ListedValue,saleValue=vehicle.SaleValue,notes=vehicle.Notes,mainPhotoUrl=vehicle.Photos.FirstOrDefault(p=>p.IsMain)?.StoragePath??vehicle.Photos.FirstOrDefault()?.StoragePath,photos=vehicle.Photos.Select(p=>new{id=p.Id,url=p.StoragePath,isMain=p.IsMain}).ToList(),documents=vehicle.Documents.Where(d=>d.ShowInCatalog).Select(d=>new{id=d.Id,name=d.Name,documentType=d.DocumentCategory.Name,fileUrl=d.StoragePath,createdAt=d.CreatedAt}).ToList()});}
    private void AllowPublicCatalogCors(){Response.Headers["Access-Control-Allow-Origin"]="*";Response.Headers["Vary"]="Origin";}
    [HttpGet("feed/xml")][AllowAnonymous][Produces("application/xml")] public async Task<IActionResult> GetXmlFeed(){var xmlContent=await _feedExportService.GenerateXmlFeedAsync();return Content(xmlContent,"application/xml",Encoding.UTF8);}
    [HttpPost("generate-ai-description")][AllowAnonymous] public IActionResult GenerateAiDescription([FromBody]GenerateAiDescriptionDto dto){var copy=_aiDescriptionService.GenerateVehicleAdDescription(dto.Brand,dto.Model,dto.Year,dto.Price,dto.FipePrice,dto.Mileage,dto.Color,dto.FuelType,dto.Transmission,dto.Optionals);return Ok(new{description=copy});}
}
